using System.Security.Cryptography;
using PerformativeMail.Sim.Primitives;

namespace PerformativeMail.Sim.Tests.Unit.Sim.Primitives;

/// <summary>
/// Covers <see cref="Bam"/> and <see cref="TrigQ15"/> (TR-sim-031, TR-sim-034; ADR-0006 sections 1
/// and 6; story AC-1 and AC-2). The table digest is the T2 cross-OS pin generated by
/// tools/GenTrigQ15 and recorded in the story's Implementation Notes. The table itself is private;
/// entry <c>i</c> is read through the public API as <c>Sin(i * 16)</c> (the index is <c>bam &gt;&gt; 4</c>).
/// All numerics are integer-only; the SHA-256 hashing lives in the test assembly only.
/// </summary>
public class TrigQ15Tests
{
    /// <summary>SHA-256 of the 8192 little-endian table bytes, recorded when tools/GenTrigQ15 was run.</summary>
    private const string ExpectedTableSha256 = "70A520195643F9EC9AA892EC529C410634068E1FFD18FA327C73B91D04261BC7";

    private static short Entry(int index) => TrigQ15.Sin((ushort)(index << 4));

    // ---- Bam (AC-2) ----

    [Theory]
    [InlineData(65_000, 1_000, 464)]
    [InlineData(0, 0, 0)]
    [InlineData(65_535, 1, 0)]
    [InlineData(65_535, 65_535, 65_534)]
    [InlineData(1, 2, 3)]
    [InlineData(32_768, 32_768, 0)]
    public void BamAdd_Vectors_WrapModulo65536(int a, int b, int expected)
    {
        // Act (the Debug Sim is built checked: an unchecked-by-design wrap must not throw)
        ushort result = Bam.Add((ushort)a, (ushort)b);

        // Assert
        Assert.Equal((ushort)expected, result);
    }

    [Theory]
    [InlineData(10, 20, 65_526)]
    [InlineData(0, 0, 0)]
    [InlineData(0, 1, 65_535)]
    [InlineData(20, 10, 10)]
    [InlineData(0, 65_535, 1)]
    [InlineData(5, 5, 0)]
    public void BamSub_Vectors_WrapModulo65536(int a, int b, int expected)
    {
        // Act
        ushort result = Bam.Sub((ushort)a, (ushort)b);

        // Assert
        Assert.Equal((ushort)expected, result);
    }

    [Fact]
    public void BamAddSub_AllPairsOnSampledGrid_AreInverses()
    {
        // Arrange / Act / Assert: (a + b) - b == a over a coarse grid covering both wrap directions.
        for (int a = 0; a < Bam.Turn; a += 257)
        {
            for (int b = 0; b < Bam.Turn; b += 263)
            {
                ushort sum = Bam.Add((ushort)a, (ushort)b);
                Assert.Equal((ushort)a, Bam.Sub(sum, (ushort)b));
                Assert.Equal((ushort)((a + b) % Bam.Turn), sum);
            }
        }
    }

    [Fact]
    public void BamConstants_Values_AreQuarterTurns()
    {
        // Assert
        Assert.Equal(65_536, Bam.Turn);
        Assert.Equal(Bam.Turn / 4, Bam.Quarter);
        Assert.Equal(Bam.Turn / 2, Bam.Half);
        Assert.Equal(Bam.Turn * 3 / 4, Bam.ThreeQuarters);
        Assert.Equal(Bam.Half, Bam.Add(Bam.Quarter, Bam.Quarter));
        Assert.Equal(0, Bam.Add(Bam.Half, Bam.Half));
        Assert.Equal(Bam.ThreeQuarters, Bam.Sub(0, Bam.Quarter));
    }

    // ---- TrigQ15 (AC-1) ----

    [Theory]
    [InlineData(0, 0)]
    [InlineData(16_384, 32_767)]
    [InlineData(32_768, 0)]
    [InlineData(49_152, -32_767)]
    public void TrigQ15Sin_CardinalAngles_AreExact(int bam, int expected)
    {
        // Act
        short result = TrigQ15.Sin((ushort)bam);

        // Assert
        Assert.Equal((short)expected, result);
    }

    [Theory]
    [InlineData(0, 32_767)]
    [InlineData(16_384, 0)]
    [InlineData(32_768, -32_767)]
    [InlineData(49_152, 0)]
    public void TrigQ15Cos_CardinalAngles_AreExact(int bam, int expected)
    {
        // Act
        short result = TrigQ15.Cos((ushort)bam);

        // Assert
        Assert.Equal((short)expected, result);
    }

    [Fact]
    public void TrigQ15Cos_AllBamInputs_EqualSinOfBamPlusQuarterTurn()
    {
        // Act / Assert over all 65 536 inputs
        for (int bam = 0; bam < Bam.Turn; bam++)
        {
            ushort angle = (ushort)bam;
            Assert.Equal(TrigQ15.Sin(unchecked((ushort)(angle + 16_384))), TrigQ15.Cos(angle));
        }
    }

    [Fact]
    public void TrigQ15Sin_AllBamInputs_UseTableIndexBamShiftedRight4()
    {
        // Assert: the low 4 bits of the angle are ignored, so 16 consecutive angles share one entry.
        for (int bam = 0; bam < Bam.Turn; bam++)
        {
            Assert.Equal(Entry(bam >> 4), TrigQ15.Sin((ushort)bam));
        }
    }

    [Fact]
    public void TrigQ15Sin_AllEntries_StayWithinQ15SymmetricRange()
    {
        // Assert: -32768 never occurs, so negation of a result cannot overflow a short.
        for (int i = 0; i < TrigQ15.TableLength; i++)
        {
            short v = Entry(i);
            Assert.InRange((int)v, -TrigQ15.One, TrigQ15.One);
        }
    }

    [Fact]
    public void TrigQ15Sin_TableSymmetry_HoldsExactly()
    {
        // Assert: a table generated with round-half-away is odd and mirror symmetric.
        for (int i = 1; i < TrigQ15.TableLength / 2; i++)
        {
            Assert.Equal(-Entry(i), Entry(i + TrigQ15.TableLength / 2));                  // sin(x + pi) = -sin(x)
            Assert.Equal(Entry(i), Entry(TrigQ15.TableLength / 2 - i));                   // sin(pi - x) = sin(x)
            Assert.Equal(-Entry(i), Entry(TrigQ15.TableLength - i));                      // sin(-x) = -sin(x)
        }

        Assert.Equal(0, Entry(0));
        Assert.Equal(0, Entry(TrigQ15.TableLength / 2));
    }

    [Fact]
    public void TrigQ15Sin_FirstHalfTurn_IsNonDecreasingUpToQuarterThenNonIncreasing()
    {
        // Assert: monotone shape of a sine over [0, pi].
        for (int i = 1; i <= TrigQ15.TableLength / 4; i++)
        {
            Assert.True(Entry(i) >= Entry(i - 1), $"entry {i} dropped below entry {i - 1}");
        }

        for (int i = TrigQ15.TableLength / 4 + 1; i <= TrigQ15.TableLength / 2; i++)
        {
            Assert.True(Entry(i) <= Entry(i - 1), $"entry {i} rose above entry {i - 1}");
        }
    }

    [Fact]
    public void TrigQ15Sin_PythagoreanIdentity_HoldsWithinQ15Rounding()
    {
        // Assert: sin^2 + cos^2 ~ 32767^2 to within the table's quantisation (integer arithmetic only).
        const long OneSquared = 32_767L * 32_767L;
        for (int bam = 0; bam < Bam.Turn; bam += 16)
        {
            long s = TrigQ15.Sin((ushort)bam);
            long c = TrigQ15.Cos((ushort)bam);
            long err = Math.Abs(s * s + c * c - OneSquared);
            Assert.True(err < 70_000L, $"bam {bam}: error {err}");
        }
    }

    [Fact]
    public void TrigQ15Table_LittleEndianBytes_MatchRecordedSha256()
    {
        // Arrange: 4096 entries * 2 bytes = 8192 bytes (the 8 KiB guardrail), little-endian.
        byte[] bytes = new byte[TrigQ15.TableLength * 2];
        for (int i = 0; i < TrigQ15.TableLength; i++)
        {
            short v = Entry(i);
            bytes[2 * i] = (byte)(v & 0xFF);
            bytes[2 * i + 1] = (byte)((v >> 8) & 0xFF);
        }

        // Act
        string digest = Convert.ToHexString(SHA256.HashData(bytes));

        // Assert
        Assert.Equal(8_192, bytes.Length);
        Assert.Equal(ExpectedTableSha256, digest);
    }

    internal static long Exercise()
    {
        long acc = 0;
        for (int bam = 0; bam < Bam.Turn; bam += 97)
        {
            ushort a = (ushort)bam;
            acc += TrigQ15.Sin(a) + TrigQ15.Cos(a) + Bam.Add(a, 123) + Bam.Sub(a, 456);
        }

        return acc;
    }
}

/// <summary>
/// Zero-allocation guardrail for <see cref="Bam"/> and <see cref="TrigQ15"/>, in the non-parallel collection so runtime
/// warm-up on other test threads cannot land in a measured window.
/// </summary>
[Collection(NonParallelCollection.Name)]
public class TrigQ15AllocationTests
{
    [Fact]
    public void BamAndTrigQ15_WarmedUp_AllocateNothing()
    {
        // Arrange: an unoptimised Sim (Debug) has the JIT optimiser disabled for the whole assembly, so
        // RuntimeHelpers.CreateSpan (the ReadOnlySpan literal table) takes the runtime's allocating
        // fallback (~64 B per call). The 0 B guardrail therefore applies to optimised builds only.
        var debuggable = (System.Diagnostics.DebuggableAttribute?)Attribute.GetCustomAttribute(
            typeof(TrigQ15).Assembly, typeof(System.Diagnostics.DebuggableAttribute));
        Assert.SkipWhen(
            debuggable is { IsJITOptimizerDisabled: true },
            "Unoptimised Sim: RuntimeHelpers.CreateSpan (ReadOnlySpan literal table) allocates ~64 B per call at Tier-0/unoptimised JIT; the 0 B guardrail applies to optimised builds only.");
        long sink = 0;

        // Act + Assert (0 B: the ReadOnlySpan literal property must not allocate per call)
        _ = AllocAssert.Zero("100 sweeps of Sin/Cos/Bam.Add/Bam.Sub", () =>
        {
            for (int i = 0; i < 100; i++)
            {
                sink += TrigQ15Tests.Exercise();
            }
        });

        // Assert
        Assert.NotEqual(long.MinValue, sink);
    }
}
